"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type IdleAnimationPrimitiveProps = ComponentProps<typeof motion.div>;

export function IdleAnimationPrimitive({ children, ...props }: IdleAnimationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {y: 0}}
      animate={{y: [-2,2,-2]}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 2.2, ease: [0.23, 1, 0.32, 1], repeat: Infinity, repeatType: "reverse", repeatDelay: 0.3 }}
      aria-hidden="true"
    >
      {children}
    </motion.div>
  );
}
